/* Load-in: the three frames start big (filling the window) and shrink to their nested sizes;
   the headline halves start behind the frame and slide outwards; the hint fades out while the
   sentence fades up. --ondo-hero-dx / -dy are the slide distances (vertical on phones). */
.ondo-hero-hint {
  opacity: 0;
}

@media (prefers-reduced-motion: no-preference) {
  .ondo-hero-frame {
    animation: ondo-hero-shrink 1.15s cubic-bezier(0.65, 0, 0.35, 1) both;
  }
  .ondo-hero-word-a {
    animation: ondo-hero-word-a 1.15s cubic-bezier(0.65, 0, 0.35, 1) both;
  }
  .ondo-hero-word-b {
    animation: ondo-hero-word-b 1.15s cubic-bezier(0.65, 0, 0.35, 1) both;
  }
  .ondo-hero-text {
    animation: ondo-hero-rise 0.8s cubic-bezier(0.22, 1, 0.36, 1) 1s both;
  }
  .ondo-hero-hint {
    animation: ondo-hero-hint 1.4s ease-out both;
  }
}

@keyframes ondo-hero-shrink {
  from { transform: scale(var(--ondo-hero-from, 2)); }
  to { transform: none; }
}

@keyframes ondo-hero-word-a {
  from { transform: translate(var(--ondo-hero-dx), var(--ondo-hero-dy)); }
  to { transform: none; }
}

@keyframes ondo-hero-word-b {
  from { transform: translate(calc(var(--ondo-hero-dx) * -1), calc(var(--ondo-hero-dy) * -1)); }
  to { transform: none; }
}

@keyframes ondo-hero-rise {
  from { opacity: 0; transform: translateY(40px); }
  to { opacity: 1; transform: none; }
}

@keyframes ondo-hero-hint {
  0%, 60% { opacity: 1; }
  100% { opacity: 0; }
}

import type { ReactNode } from "react";
import { cn } from "@foundry/foundry-utils";
import { OndoPlaceholder } from "@foundry/ondo-placeholder";
import "./ondo-hero.css";

export interface OndoHeroProps {
  /** the headline's first half, left of (above) the frame */
  lead: string;
  /** the headline's second half, right of (below) the frame */
  trail: string;
  /** the serif sentence under the frame */
  text: string;
  /** a small hint shown while the hero loads in (e.g. "Scroll to explore") */
  hint?: string;
  /** the three frames, outer to inner (square videos or images). Plain surfaces when empty */
  frames?: [ReactNode?, ReactNode?, ReactNode?];
  className?: string;
}

const serif = "font-[family-name:var(--ondo-serif,var(--typeface-display))]";

// outer, middle, inner: size as a share of the frame, corner radius, the scale they load in
// from (so all three start about the same screen-filling size), placeholder tone
const layers = [
  {
    size: "size-full",
    radius: "rounded-[2rem] xl:rounded-[2.5rem]",
    from: "[--ondo-hero-from:1.9]",
    tone: "muted" as const,
  },
  {
    size: "size-[86%]",
    radius: "rounded-[1.75rem] xl:rounded-[2.25rem]",
    from: "[--ondo-hero-from:2.2]",
    tone: "deep" as const,
  },
  {
    size: "size-[61%]",
    radius: "rounded-[1.375rem] xl:rounded-[1.75rem]",
    from: "[--ondo-hero-from:2.9]",
    tone: "muted" as const,
  },
];

const word =
  "relative z-0 block font-display text-[2.75rem] leading-[1.1] font-medium tracking-[-0.035em] whitespace-nowrap text-foreground xl:text-[3.5rem]";

/** Split headline around a nested-frame "tunnel", 125% of the window tall. */
export function OndoHero({
  lead,
  trail,
  text,
  hint,
  frames,
  className,
}: OndoHeroProps) {
  return (
    <section
      className={cn(
        "relative min-h-[125svh] overflow-x-clip bg-background",
        className,
      )}
    >
      <h1 className="sr-only">{`${lead} ${trail}`}</h1>
      {/* the first window: the stage centred, the sentence at its foot; the band runs on to 125svh */}
      <div className="flex min-h-svh flex-col items-center px-gutter pt-[7.5rem] pb-9 lg:pb-10">
        <div className="flex w-full flex-1 items-center justify-center">
          <div
            aria-hidden
            className="flex w-full flex-col items-center gap-10 [--ondo-hero-dx:0px] [--ondo-hero-dy:175px] lg:grid lg:grid-cols-[1fr_auto_1fr] lg:gap-8 lg:[--ondo-hero-dx:260px] lg:[--ondo-hero-dy:0px] xl:gap-12"
          >
            <span className={cn(word, "ondo-hero-word-a lg:justify-self-end")}>
              {lead}
            </span>
            <div className="relative z-10 grid size-[18.75rem] shrink-0 place-items-center lg:size-[22rem] xl:size-[28.3rem]">
              {layers.map((layer, i) => (
                <div
                  key={i}
                  className={cn(
                    "ondo-hero-frame absolute overflow-clip [transform-origin:center]",
                    layer.size,
                    layer.radius,
                    layer.from,
                    i > 0 &&
                      "shadow-[0_0_0_1px_color-mix(in_oklab,var(--background)_35%,transparent)]",
                  )}
                >
                  {frames?.[i] ?? <OndoPlaceholder tone={layer.tone} />}
                </div>
              ))}
            </div>
            <span
              className={cn(word, "ondo-hero-word-b lg:justify-self-start")}
            >
              {trail}
            </span>
          </div>
        </div>
        <div className="relative mt-10">
          {hint && (
            <p
              aria-hidden
              className="ondo-hero-hint absolute inset-x-0 bottom-full mb-6 text-center text-xs font-medium text-muted-foreground"
            >
              {hint}
            </p>
          )}
          <p
            className={cn(
              "ondo-hero-text max-w-[22rem] text-center text-base leading-[1.32] text-foreground lg:max-w-[29.5rem] lg:text-xl lg:leading-[1.32]",
              serif,
            )}
          >
            {text}
          </p>
        </div>
      </div>
    </section>
  );
}
